import { Type } from '@sinclair/typebox';
import type { ExtensionAPI } from '@earendil-works/pi-coding-agent';

export default function (pi: ExtensionAPI) {
  pi.registerFlag('note-prefix', {
    description: '原样添加到输出前的前缀',
    type: 'string',
    default: '',
  });
  pi.registerTool({
    name: 'echo_note',
    label: 'Echo Note',
    description: '返回 note-prefix 与 text 的直接拼接，不修改文本。',
    parameters: Type.Object({ text: Type.String() }),
    async execute(_id, { text }) {
      return {
        content: [{ type: 'text', text: (pi.getFlag('note-prefix') as string) + text }],
        details: {},
      };
    },
  });
}

